//! Screen + window capture.
//!
//! Backed by `xcap`, which wraps the platform-native capture APIs:
//! - macOS: `CGDisplayCreateImage` / `CGWindowListCreateImage`
//! - Windows: DXGI desktop duplication / `BitBlt` fallback
//! - Linux: X11 `XGetImage` or PipeWire (Wayland)
//!
//! Captures arrive as `RgbaImage`; we encode to PNG before returning so
//! the wire payload is browser-displayable as `data:image/png;base64,…`
//! without an extra round-trip through `image` on the JS side.
//!
//! Dispatch is generated by `#[tynd::handler]` (U10), wrapped by the
//! per-method ACL gate on `captureScreen` / `captureWindow`.

use base64::{engine::general_purpose::STANDARD, Engine as _};
use image::ImageFormat;
use serde_json::{json, Value};
use xcap::{Monitor, Window};

use crate::ipc_error::IpcError;

mod inner {
    use super::{capture_screen_impl, capture_window_impl, list_monitors_impl, list_windows_impl};
    use crate::tynd;
    use serde_json::Value;

    /// Marker for the `#[tynd::handler]` dispatch table.
    #[derive(Debug, Default)]
    pub struct ScreenshotApi;

    #[tynd::handler(api = "screenshot")]
    impl ScreenshotApi {
        /// Capture the framebuffer of the monitor at `monitorIndex`
        /// (default `0`, i.e. the primary display). Returns
        /// `{ width, height, data }` where `data` is a base64-encoded
        /// PNG.
        pub fn capture_screen(monitor_index: Option<u64>) -> Result<Value, String> {
            capture_screen_impl(monitor_index.unwrap_or(0) as usize)
        }

        /// Capture a single window by `windowId` (as returned by
        /// `listWindows`). Returns the same `{ width, height, data }`
        /// PNG shape as `captureScreen`.
        pub fn capture_window(window_id: u64) -> Result<Value, String> {
            capture_window_impl(window_id)
        }

        /// List every monitor known to the OS, with `id`, `name`, pixel
        /// dimensions, scale factor, and a `primary` flag.
        pub fn list_monitors() -> Result<Value, String> {
            list_monitors_impl()
        }

        /// List every top-level window with `id`, `title`, `app_name`,
        /// and pixel dimensions.
        pub fn list_windows() -> Result<Value, String> {
            list_windows_impl()
        }
    }
}

/// Public dispatch wrapper — interposes the ACL gate on the two
/// privacy-sensitive `capture*` methods before delegating to the
/// macro-generated table inside [`inner`].
pub fn dispatch(method: &str, args: &Value) -> Result<Value, String> {
    // W3.2 — ACL gate. The two `capture*` methods are the privacy-
    // sensitive surface (anything that returns a frame buffer of the
    // user's screen). The `list*` introspection methods are kept open
    // so admin / settings UIs can populate a monitor / window picker
    // *before* the user grants `screenshot:captureScreen` — same
    // posture as `biometric.isAvailable`.
    #[cfg(feature = "api-acl")]
    {
        let needs_gate = matches!(method, "captureScreen" | "captureWindow");
        if needs_gate {
            let cmd = format!("screenshot:{method}");
            if !crate::os::acl::authority().is_allowed(&cmd, None, None, None) {
                return Err(
                    IpcError::new("screenshot", method, "permission denied by ACL").into_string(),
                );
            }
        }
    }
    inner::dispatch(method, args)
}

fn list_monitors_impl() -> Result<Value, String> {
    let monitors = Monitor::all()
        .map_err(|e| IpcError::new("screenshot", "listMonitors", e).into_string())?;
    let arr: Vec<Value> = monitors
        .iter()
        .map(|m| {
            json!({
                "id": m.id(),
                "name": m.name(),
                "width": m.width(),
                "height": m.height(),
                "scale": m.scale_factor(),
                "primary": m.is_primary(),
            })
        })
        .collect();
    Ok(Value::Array(arr))
}

fn list_windows_impl() -> Result<Value, String> {
    let windows = Window::all()
        .map_err(|e| IpcError::new("screenshot", "listWindows", e).into_string())?;
    let arr: Vec<Value> = windows
        .iter()
        .map(|w| {
            json!({
                "id": w.id(),
                "title": w.title(),
                "app_name": w.app_name(),
                "width": w.width(),
                "height": w.height(),
            })
        })
        .collect();
    Ok(Value::Array(arr))
}

fn capture_screen_impl(idx: usize) -> Result<Value, String> {
    let monitors = Monitor::all()
        .map_err(|e| IpcError::new("screenshot", "captureScreen", e).into_string())?;
    if monitors.is_empty() {
        return Err(
            IpcError::new("screenshot", "captureScreen", "no monitors detected").into_string(),
        );
    }
    let monitor = monitors.get(idx).ok_or_else(|| {
        IpcError::new("screenshot", "captureScreen", format!("monitor {idx} out of range"))
            .into_string()
    })?;

    let img = monitor
        .capture_image()
        .map_err(|e| IpcError::new("screenshot", "captureScreen", e).into_string())?;
    encode_png(img.width(), img.height(), &img.into_raw())
}

fn capture_window_impl(id: u64) -> Result<Value, String> {
    let windows = Window::all()
        .map_err(|e| IpcError::new("screenshot", "captureWindow", e).into_string())?;
    let id_u32: u32 = u32::try_from(id).map_err(|_| {
        IpcError::new(
            "screenshot",
            "captureWindow",
            format!("window_id {id} out of u32 range"),
        )
        .into_string()
    })?;
    let window = windows.into_iter().find(|w| w.id() == id_u32).ok_or_else(|| {
        IpcError::new("screenshot", "captureWindow", format!("window {id} not found")).into_string()
    })?;

    let img = window
        .capture_image()
        .map_err(|e| IpcError::new("screenshot", "captureWindow", e).into_string())?;
    encode_png(img.width(), img.height(), &img.into_raw())
}

/// Encode RGBA bytes as PNG and wrap in the standard `{ width, height,
/// data }` shape. `data` is base64 to keep the JSON wire contract intact —
/// a future zero-copy path can route through `tynd-bin://` (see
/// `scheme_bin.rs`) the same way `fs.readBinary` does, but PNG-encoded
/// screenshots are typically <2 MB so the base64 cost is acceptable.
fn encode_png(width: u32, height: u32, rgba: &[u8]) -> Result<Value, String> {
    if width == 0 || height == 0 {
        return Err(IpcError::new(
            "screenshot",
            "encode_png",
            format!("invalid capture dimensions ({width}x{height})"),
        )
        .into_string());
    }
    let buffer = image::RgbaImage::from_raw(width, height, rgba.to_vec()).ok_or_else(|| {
        IpcError::new("screenshot", "encode_png", "malformed RGBA buffer").into_string()
    })?;
    let mut png = Vec::with_capacity((width as usize) * (height as usize));
    let mut cursor = std::io::Cursor::new(&mut png);
    buffer
        .write_to(&mut cursor, ImageFormat::Png)
        .map_err(|e| IpcError::new("screenshot", "encode_png", e).into_string())?;
    Ok(json!({
        "width": width,
        "height": height,
        "data": STANDARD.encode(&png),
    }))
}
